#include "discover.h"
#include "parse_evd.h"
#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_EVENTS 256

typedef struct {
    char file[256];
    char name[128];
    char fields[512];
    int written;
} event_desc;

static int by_filename(const void *a, const void *b) {
    const event_desc *ea = a;
    const event_desc *eb = b;
    return strcmp(ea->file, eb->file);
}

static int load_events(event_desc *events) {
    DIR *d = opendir("/app/rivetbay/evd");
    if (!d) return -1;
    int n = 0;
    struct dirent *ent;
    while (n < MAX_EVENTS && (ent = readdir(d)) != NULL) {
        size_t len = strlen(ent->d_name);
        if (len < 5 || strcmp(ent->d_name + len - 4, ".evd") != 0) continue;
        char path[512];
        snprintf(path, sizeof(path), "/app/rivetbay/evd/%s", ent->d_name);
        if (parse_evd_file(path, events[n].name, events[n].fields,
                           sizeof(events[n].fields)) != 0)
            continue;
        snprintf(events[n].file, sizeof(events[n].file), "%s", ent->d_name);
        events[n].written = 0;
        n++;
    }
    closedir(d);
    qsort(events, (size_t)n, sizeof(events[0]), by_filename);
    return n;
}

static int load_prior_names(char names[][128]) {
    FILE *f = fopen("/app/rivetbay/intake/current.ledger", "r");
    if (!f) return 0;
    int n = 0;
    char line[1024];
    while (n < MAX_EVENTS && fgets(line, sizeof(line), f)) {
        char *bar = strchr(line, '|');
        if (!bar) continue;
        *bar = 0;
        char *name = line;
        while (*name == ' ' || *name == '\t') name++;
        if (!*name) continue;
        snprintf(names[n], 128, "%s", name);
        n++;
    }
    fclose(f);
    return n;
}

static void write_event(FILE *out, event_desc *event) {
    fprintf(out, "%s|evd/%s|%s\n", event->name, event->file, event->fields);
    event->written = 1;
}

void discover_all(void) {
    event_desc events[MAX_EVENTS];
    char prior[MAX_EVENTS][128];
    int nprior = load_prior_names(prior);
    int nevents = load_events(events);
    if (nevents < 0) return;

    FILE *out = fopen("/app/rivetbay/intake/current.ledger", "w");
    if (!out) return;

    for (int p = 0; p < nprior; p++) {
        for (int i = 0; i < nevents; i++) {
            if (!events[i].written && strcmp(prior[p], events[i].name) == 0) {
                write_event(out, &events[i]);
                break;
            }
        }
    }
    for (int i = 0; i < nevents; i++)
        if (!events[i].written) write_event(out, &events[i]);

    fclose(out);
}
